BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SELECT no_plan();
CREATE TEMP TABLE initial_original_fixtures(version INTEGER,manifest JSONB,scan TEXT,generation TEXT,digest TEXT);
INSERT INTO initial_original_fixtures VALUES (7,'{"schema_version": 7, "items": [{"kind": "image", "source": {"media_id": "00000000-0000-4000-8000-000000000030", "content_type": "image/heif", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "prepared": {"media_id": "00000000-0000-4000-8000-000000000031", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "coordinate_basis": "prepared_image_top_left_v1", "focus_region": {"x": 0.1, "y": 0.2, "width": 0.3, "height": 0.4, "source": "user_selection"}}, {"kind": "description", "text": "  Synthetic 🦋 context.  "}, {"kind": "video", "source": {"media_id": "00000000-0000-4000-8000-000000000032", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "playback": {"media_id": "00000000-0000-4000-8000-000000000033", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "frames": [{"media_id": "00000000-0000-4000-8000-000000000034", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, {"media_id": "00000000-0000-4000-8000-000000000035", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}], "audio": {"source": {"media_id": "00000000-0000-4000-8000-000000000036", "content_type": "audio/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "prepared": {"media_id": "00000000-0000-4000-8000-000000000037", "content_type": "audio/wav", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}}]}'::JSONB,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000020','58b3f5c8bd1e027163d3a3c18e5dd0d7f2b8dcf059086f05626b212303a7975c');
INSERT INTO initial_original_fixtures VALUES (8,'{"schema_version": 8, "items": [{"kind": "image", "source": {"media_id": "00000000-0000-4000-8000-000000000030", "content_type": "image/heif", "byte_count": 33554432, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "prepared": {"media_id": "00000000-0000-4000-8000-000000000031", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "coordinate_basis": "prepared_image_top_left_v1", "focus_region": {"x": 0.1, "y": 0.2, "width": 0.3, "height": 0.4, "source": "user_selection"}}, {"kind": "description", "text": "  Synthetic 🦋 context.  "}, {"kind": "video", "source": {"media_id": "00000000-0000-4000-8000-000000000032", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "playback": {"media_id": "00000000-0000-4000-8000-000000000033", "content_type": "video/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "frames": [{"media_id": "00000000-0000-4000-8000-000000000034", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, {"media_id": "00000000-0000-4000-8000-000000000035", "content_type": "image/jpeg", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}], "audio": {"source": {"media_id": "00000000-0000-4000-8000-000000000036", "content_type": "audio/mp4", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}, "prepared": {"media_id": "00000000-0000-4000-8000-000000000037", "content_type": "audio/wav", "byte_count": 100, "sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}}]}'::JSONB,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000020','cac3c1b889ab9defa3185a3faf675296c0f0cacfbbdbf1a2f7fa25874c3072e0');
SELECT is(internal.initial_evidence_contract(manifest,scan,generation)->>'evidence_digest',digest,
    'shared typed digest matches initial manifest V'||version) FROM initial_original_fixtures;
SELECT is(jsonb_array_length(internal.initial_evidence_contract(manifest,scan,generation)->'items'),8,
    'source/prepared/video artifact roles preserved V'||version) FROM initial_original_fixtures;
SELECT is(internal.initial_evidence_contract(jsonb_set(manifest,'{schema_version}',to_jsonb(version::NUMERIC(2,1))),scan,generation)->>'evidence_digest',digest,
    'numeric schema spelling preserves typed digest V'||version) FROM initial_original_fixtures;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',
    jsonb_set(manifest,'{schema_version}','7'),scan,generation),'22023','invalid_analysis_history',
    'large source cannot enter V7') FROM initial_original_fixtures WHERE version=8;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',
    jsonb_set(manifest,'{items,0,source,byte_count}','33554433'),scan,generation),'22023','invalid_analysis_history',
    'V8 original per-artifact cap is strict') FROM initial_original_fixtures WHERE version=8;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',
    jsonb_set(manifest,'{items,0,prepared,byte_count}','5242881'),scan,generation),'22023','invalid_analysis_history',
    'V8 prepared bytes retain the provider cap') FROM initial_original_fixtures WHERE version=8;
SELECT throws_ok(pg_catalog.format('SELECT internal.initial_evidence_contract(%L::jsonb,%L,%L)',
    jsonb_set(manifest,'{schema_version}','null'),scan,generation),'22023','invalid_analysis_history',
    'null manifest version is not admitted') FROM initial_original_fixtures WHERE version=8;
SELECT ok(NOT has_function_privilege(role,'internal.initial_evidence_contract(jsonb,text,text)','EXECUTE'),
    role||' cannot directly parse/authorize private original evidence') FROM (VALUES('anon'),('authenticated'),('service_role')) roles(role);
SELECT ok(NOT has_function_privilege(role,'internal.resolve_initial_history_media(uuid,uuid,uuid,uuid)','EXECUTE'),
    role||' cannot bypass completed-media resolver fences') FROM (VALUES('anon'),('authenticated'),('service_role')) roles(role);
SELECT is(provolatile::TEXT,'s','initial evidence canonical validator preserves stable classification')
    FROM pg_proc WHERE oid='internal.initial_evidence_contract(jsonb,text,text)'::regprocedure;
SELECT * FROM finish();
ROLLBACK;
